export function translateStatic(language: AppLanguage, key: string): string {
  if (language === 'de') {
    return key;
  }
  return TRANSLATIONS[language]?.[key] ?? TRANSLATIONS['en-US']?.[key] ?? key;
}

@Injectable({ providedIn: 'root' })
export class LanguageService {
  private static readonly storageKey = 'gigflow-language';
  private readonly document = inject(DOCUMENT);
  private readonly currentLanguage = signal<AppLanguage>(this.readInitialLanguage());

  readonly language = this.currentLanguage.asReadonly();
  readonly options = LANGUAGE_OPTIONS;

  constructor() {
    this.applyDocumentLanguage(this.language());
  }

  translate(key: string, params: Record<string, string | number> = {}): string {
    let result = translateStatic(this.language(), key);
    for (const [name, value] of Object.entries(params)) {
      result = result.split(`{{${name}}}`).join(String(value));
    }
    return result;
  }

  locale(): string {
    return this.language();
  }

  setLanguage(language: AppLanguage): void {
    if (!LANGUAGES.includes(language)) {
      return;
    }
    this.currentLanguage.set(language);
    this.applyDocumentLanguage(language);
    try {
      this.document.defaultView?.localStorage.setItem(LanguageService.storageKey, language);
    } catch {
      return;
    }
  }

  private readInitialLanguage(): AppLanguage {
    try {
      const saved = this.document.defaultView?.localStorage.getItem(LanguageService.storageKey);
      if (saved && LANGUAGES.includes(saved as AppLanguage)) {
        return saved as AppLanguage;
      }
    } catch {
      return 'de';
    }
    return 'de';
  }

  private applyDocumentLanguage(language: AppLanguage): void {
    this.document.documentElement.lang = language;
  }
}
